package com.leetcode.backend.controller;
import com.leetcode.backend.model.*; import com.leetcode.backend.repository.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/problems/{problemId}/note") public class ProblemNoteController {private final ProblemNoteRepository notes;private final UserRepository users;private final ProblemRepository problems;public ProblemNoteController(ProblemNoteRepository n,UserRepository u,ProblemRepository p){notes=n;users=u;problems=p;} private User user(Authentication a){return users.findByUsername(a.getName()).orElseThrow(()->new RuntimeException("User not found."));}
 @GetMapping public ResponseEntity<ProblemNote> get(@PathVariable Long problemId,Authentication a){return notes.findByUserIdAndProblemId(user(a).getId(),problemId).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}
 @PutMapping public ProblemNote put(@PathVariable Long problemId,@RequestBody ProblemNote body,Authentication a){User u=user(a);ProblemNote n=notes.findByUserIdAndProblemId(u.getId(),problemId).orElseGet(ProblemNote::new);n.setUser(u);n.setProblem(problems.findById(problemId).orElseThrow(()->new RuntimeException("Problem not found.")));n.setContent(body.getContent());return notes.save(n);}
 @DeleteMapping public ResponseEntity<Void> delete(@PathVariable Long problemId,Authentication a){notes.findByUserIdAndProblemId(user(a).getId(),problemId).ifPresent(notes::delete);return ResponseEntity.noContent().build();}}
